const body = $json.body ?? $json;
if (!Array.isArray(body.scenes) || body.scenes.length === 0) {
  throw new Error('scenes must be a non-empty array');
}
for (const [i, scene] of body.scenes.entries()) {
  if (!scene || typeof scene.text !== 'string' || !scene.text.trim()) {
    throw new Error(`scene ${i + 1}: text is required`);
  }
  if (!Array.isArray(scene.searchTerms) || scene.searchTerms.length === 0) {
    throw new Error(`scene ${i + 1}: searchTerms must be a non-empty array`);
  }
}
return [{
  json: {
    scenes: body.scenes,
    config: {
      paddingBack: Number.isFinite(body.paddingBack) ? body.paddingBack : 500,
      music: body.music ?? 'chill',
      captionPosition: body.captionPosition ?? 'bottom',
      captionBackgroundColor: body.captionBackgroundColor ?? 'blue',
      voice: body.voice ?? 'af_heart',
      orientation: 'portrait',
      musicVolume: body.musicVolume ?? 'low'
    }
  }
}];
